(7407634, 1166981, 69838, '<td valign="top">I''m confused about the subject.  adding focus to at least one object such as the red car would make this less confusing.  Rotating the picture slightly clockwise to eliminate the lean would also help.  As it is, this image almost looks like a misfire, as if you were walking and accidentally pressed the shutter button.</td>', 'I''m confused about the subject.  adding focus to at least one object such as the red car would make this less confusing.  Rotating the picture slightly clockwise to eliminate the lean would also help.  As it is, this image almost looks like a misfire, as if you were walking and accidentally pressed the shutter button.', '2015-10-03 14:58:15.000000', NULL, 1),
(7407737, 1167064, 149964, '<td valign="top">Fabulous colours and great for challenge.</td>', 'Fabulous colours and great for challenge.', '2015-10-04 13:50:25.000000', NULL, 1),
(7407738, 1167029, 149964, '<td valign="top">Love this and especially the juxtaposition of the colours.</td>', 'Love this and especially the juxtaposition of the colours.', '2015-10-04 13:51:12.000000', NULL, 1),
(7407739, 1167057, 149964, '<td valign="top">Love this! My only niggle(and it hasn''t detracted from the mark) is the very very bright light at the top which detracts a little from the snail.</td>', 'Love this! My only niggle(and it hasn''t detracted from the mark) is the very very bright light at the top which detracts a little from the snail.', '2015-10-04 13:52:10.000000', NULL, 1),
(7407740, 1166759, 149964, '<td valign="top">One of my favourites. And now I''m going to sound really picky (but hasn''t changed the mark I gave)..... but I''d like to tilt the top of the bottle a micro fraction more to the left straighten to it up. OK, that''s pedantry; I''ll go now.</td>', 'One of my favourites. And now I''m going to sound really picky (but hasn''t changed the mark I gave)..... but I''d like to tilt the top of the bottle a micro fraction more to the left straighten to it up. OK, that''s pedantry; I''ll go now.', '2015-10-04 13:52:50.000000', NULL, 1),
(7407741, 1167077, 149964, '<td valign="top">This is an image which gets better every time I look at it. It''s like there are two parallel lives going on...the shadowy, slightly chaotic upper one highlighting the crisp serenity of the lower one. One of my favourites.</td>', 'This is an image which gets better every time I look at it. It''s like there are two parallel lives going on...the shadowy, slightly chaotic upper one highlighting the crisp serenity of the lower one. One of my favourites.', '2015-10-04 13:53:10.000000', NULL, 1),
(7407742, 1167096, 149964, '<td valign="top">Really like the softness that this portrays.</td>', 'Really like the softness that this portrays.', '2015-10-04 13:54:29.000000', NULL, 1),
(7407743, 1167126, 149964, '<td valign="top">Great capture</td>', 'Great capture', '2015-10-04 13:54:52.000000', NULL, 1),
(7407744, 1167034, 149964, '<td valign="top">Really love the colours of this.</td>', 'Really love the colours of this.', '2015-10-04 13:55:19.000000', NULL, 1),
