(7407759, 1167041, 149964, '<td valign="top">Not really getting ''bokeh'' from this.</td>', 'Not really getting ''bokeh'' from this.', '2015-10-04 14:08:18.000000', NULL, 1),
(7407834, 1166892, 94265, '<td valign="top">One of the few entries in this challenge that actually uses bokeh as an interesting feature of the photo, and not just a photo that happens to have bokeh as normal. Nice job, I like the colours.</td>', 'One of the few entries in this challenge that actually uses bokeh as an interesting feature of the photo, and not just a photo that happens to have bokeh as normal. Nice job, I like the colours.', '2015-10-04 18:55:31.000000', NULL, 1),
