(7407856, 1167043, 150277, '<td valign="top">So soft and pretty. In my top 2.</td>', 'So soft and pretty. In my top 2.', '2015-10-04 20:54:13.000000', NULL, 1),
(7407857, 1167063, 150277, '<td valign="top">Lovely, I like the delicate subject surrounded by such a soft color.</td>', 'Lovely, I like the delicate subject surrounded by such a soft color.', '2015-10-04 20:54:56.000000', NULL, 1),
