INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7408253, 1167057, 156466, '<td valign="top">The brightness and color of the bokeh is pulling my eyes away from the subject.  If I scroll up and hide the big light bar at the top it''s a much better photograph.</td>', 'The brightness and color of the bokeh is pulling my eyes away from the subject.  If I scroll up and hide the big light bar at the top it''s a much better photograph.', '2015-10-06 10:11:19.000000', NULL, 1),
(7408254, 1166969, 156466, '<td valign="top">Really lovely colors and processing and one of my favorites.  With that said, I see this more as bokeh-as-subject instead of bokeh-enhancing-the-subject as described in the challenge.  Still the top score for me so far.</td>', 'Really lovely colors and processing and one of my favorites.  With that said, I see this more as bokeh-as-subject instead of bokeh-enhancing-the-subject as described in the challenge.  Still the top score for me so far.', '2015-10-06 10:14:50.000000', NULL, 1),
(7408255, 1166803, 156466, '<td valign="top">Why, oh why, did you feel the need to texture?!  It sucks the OOF qualities right out of the otherwise very nice bokeh you have.  I suspect we''ve been through this before.</td>', 'Why, oh why, did you feel the need to texture?!  It sucks the OOF qualities right out of the otherwise very nice bokeh you have.  I suspect we''ve been through this before.', '2015-10-06 10:16:31.000000', NULL, 1),
(7408256, 1166883, 156466, '<td valign="top">When the OOF areas have highly structured noise patterns the bokeh becomes none existent.  I''d rather have less sharpness here and more boken to fit the challenge.</td>', 'When the OOF areas have highly structured noise patterns the bokeh becomes none existent.  I''d rather have less sharpness here and more boken to fit the challenge.', '2015-10-06 10:17:38.000000', NULL, 1),
